package com.learningspace;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.content.res.Configuration;import android.view.View;import android.widget.*;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;
public class LearningWidget extends AppWidgetProvider {
 String type(){return "today";}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)render(c,m,id,type());}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle b){render(c,m,id,type());}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(Intent.ACTION_DATE_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())||Intent.ACTION_CONFIGURATION_CHANGED.equals(i.getAction()))updateAll(c);}
 public static void updateAll(Context c){Class<?>[] classes={TodayWidget.class,StreakWidget.class,GoalWidget.class,NextWidget.class,ReadingWidget.class,WeekWidget.class,OverviewWidget.class};String[] types={"today","streak","goal","next","reading","week","overview"};AppWidgetManager m=AppWidgetManager.getInstance(c);for(int i=0;i<classes.length;i++)for(int id:m.getAppWidgetIds(new ComponentName(c,classes[i])))render(c,m,id,types[i]);}
 static PendingIntent open(Context c,int request,String path){return PendingIntent.getActivity(c,request,new Intent(c,MainActivity.class).putExtra("path",path).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean dark(Context c,int id,JSONObject j){String preference=c.getSharedPreferences("widgets",0).getString("theme_"+id,"app");if(preference.equals("app"))preference=c.getSharedPreferences("appearance",0).getString("theme",j.optString("themePreference","system"));return preference.equals("forest")||preference.equals("dark")||(preference.equals("system")&&(c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);}
 static void render(Context c,AppWidgetManager manager,int id,String type){JSONObject j=WidgetStore.read(c);WidgetMetrics m=WidgetMetrics.from(j,Instant.now());Bundle options=manager.getAppWidgetOptions(id);int height=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,160),width=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,250);boolean compact=height<100||((type.equals("streak")||type.equals("overview"))&&width<170),overview=type.equals("overview")&&!compact,streak=type.equals("streak")&&!compact,dark=dark(c,id,j);int layout=compact?R.layout.widget_compact:overview?(height>=190&&width>=240?R.layout.widget_overview:R.layout.widget_overview_small):streak?R.layout.widget_streak:R.layout.widget_card;RemoteViews v=new RemoteViews(c.getPackageName(),layout);int ink=dark?0xffe8f1de:0xff294331,muted=dark?0xffb7c9af:0xff53684d;v.setInt(R.id.widget_root,"setBackgroundResource",dark?R.drawable.widget_forest:R.drawable.widget_light);v.setTextColor(R.id.label,muted);v.setTextColor(R.id.freshness,muted);v.setTextColor(R.id.refresh,ink);v.setOnClickPendingIntent(R.id.refresh,open(c,id*10+9,"?page=today"));v.setContentDescription(R.id.refresh,"Open app to refresh local progress and try Wi-Fi sync");String path="?page=today",label="TODAY’S PLAN",big=m.minutes+" / "+m.goal+" min",detail=m.encouragement;JSONArray next=j.optJSONArray("next");JSONObject first=next!=null?next.optJSONObject(0):null;String nextTitle=first!=null?first.optString("title"):"Choose your next good step";
 if(overview){v.setTextViewText(R.id.daily_amount,m.minutes+" / "+m.goal+" min today");v.setTextColor(R.id.daily_amount,ink);label="LEARNING SPACE";v.setImageViewBitmap(R.id.ring,WidgetGraphics.ring((int)(100*c.getResources().getDisplayMetrics().density),m.percent(),dark));v.setContentDescription(R.id.ring,m.minutes+" of "+m.goal+" minutes today, "+m.percent()+" percent");v.setTextViewText(R.id.metric_streak,m.streak+" day streak");v.setTextViewText(R.id.metric_week,m.weekMinutes+" min · last 7 days");for(int metric:new int[]{R.id.metric_streak,R.id.metric_week}){v.setTextColor(metric,ink);v.setInt(metric,"setBackgroundResource",dark?R.drawable.widget_tile_dark:R.drawable.widget_tile);v.setOnClickPendingIntent(metric,open(c,id*10+2,"?page=activity"));}v.setTextViewText(R.id.next_line,(m.current?"Next: ":"Saved step: ")+nextTitle);v.setTextColor(R.id.next_line,muted);v.setOnClickPendingIntent(R.id.next_line,open(c,id*10+3,first!=null?"?resource="+first.optString("resourceId"):"?page=library"));v.setViewVisibility(R.id.next_line,height<165?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.freshness,height<145?View.GONE:View.VISIBLE);}
 else{
  if(type.equals("streak")){label="YOUR LEARNING STREAK";big=compact?m.streak+" day streak":String.valueOf(m.streak);detail=m.encouragement;path="?page=activity";if(streak){v.setTextColor(R.id.unit,ink);v.setTextViewText(R.id.unit,(m.streak==1?"day":"days")+" of learning");v.setImageViewResource(R.id.mascot,m.minutes>=m.goal?R.drawable.sprout_celebrate:R.drawable.sprout_buddy);v.setTextViewTextSize(R.id.big,android.util.TypedValue.COMPLEX_UNIT_SP,(float)Math.min(height<180?34:50,Math.max(20,(width-112)/(Math.max(1,String.valueOf(m.streak).length())*.65))));v.setInt(R.id.detail,"setMaxLines",height<180?1:3);}}
  else if(type.equals("goal")){label="YOUR DAILY GOAL";detail=m.minutes>=m.goal?m.encouragement:(m.goal-m.minutes)+" more minutes to your goal";}
  else if(type.equals("week")){label="THE LAST 7 DAYS";big=m.weekMinutes+" min";detail=m.weekDays+" learning "+(m.weekDays==1?"day":"days")+" · a little at a time";path="?page=activity";if(!compact){v.setViewVisibility(R.id.chart,height>=180?View.VISIBLE:View.GONE);v.setImageViewBitmap(R.id.chart,WidgetGraphics.week((int)(220*c.getResources().getDisplayMetrics().density),(int)(54*c.getResources().getDisplayMetrics().density),m,dark));}}
  else if(type.equals("reading")){label="A FEW PAGES AT A TIME";JSONObject book=j.optJSONObject("reading");if(book!=null){big=book.optString("title");detail=book.optInt("progress")+"% complete · "+book.optString("chapter");path="?resource="+book.optString("resourceId");}else{big="Make room for a book";detail="Add a PDF, EPUB, or reading plan";path="?page=library";}}
  else if(type.equals("next")){label=m.current?"YOUR NEXT STEP":"SAVED NEXT STEP";big=nextTitle;detail=first!=null?first.optString("course")+" · "+first.optInt("minutes")+" min":"Open your library to choose a lesson";path=first!=null?"?resource="+first.optString("resourceId"):"?page=library";}
  else if(type.equals("overview")){label="LEARNING SPACE";big=m.minutes+"/"+m.goal+" min · "+m.streak+"d";}
  else if(m.current&&next!=null&&next.length()>0){StringBuilder lines=new StringBuilder();for(int k=0;k<next.length();k++){JSONObject item=next.optJSONObject(k);if(k>0)lines.append("\n");lines.append(k+1).append(". ").append(item.optString("title")).append(" · ").append(item.optInt("minutes")).append(" min");}detail=lines.toString();}else if(!m.current)detail="A fresh day. Open the app for today’s plan.";
  v.setTextViewText(R.id.big,big);v.setTextViewText(R.id.detail,detail);v.setTextColor(R.id.big,ink);v.setTextColor(R.id.detail,muted);if(!streak)v.setTextViewTextSize(R.id.big,android.util.TypedValue.COMPLEX_UNIT_SP,compact?(width<170?14:18):type.equals("goal")||type.equals("today")?28:22);if(!streak){boolean showProgress=type.equals("goal")||type.equals("today")||type.equals("overview");v.setViewVisibility(R.id.progress,showProgress?View.VISIBLE:View.GONE);if(showProgress)v.setImageViewBitmap(R.id.progress,WidgetGraphics.bar((int)(Math.max(64,width-32)*c.getResources().getDisplayMetrics().density),(int)(5*c.getResources().getDisplayMetrics().density),m.percent(),dark));}if(compact){v.setViewVisibility(R.id.refresh,View.GONE);v.setViewVisibility(R.id.detail,View.GONE);v.setViewVisibility(R.id.freshness,View.GONE);v.setViewVisibility(R.id.progress,View.GONE);v.setTextViewTextSize(R.id.label,android.util.TypedValue.COMPLEX_UNIT_SP,8);}
 }
 String freshness="Open the app to begin";if(m.hasData)try{freshness=(m.current?"Updated ":"Saved ")+Instant.parse(j.getString("updatedAt")).atZone(ZoneId.of(j.getString("timezone"))).format(DateTimeFormatter.ofPattern(m.current?"HH:mm":"MMM d, HH:mm"));}catch(Exception ignored){}v.setTextViewText(R.id.label,label);v.setTextViewText(R.id.freshness,freshness);v.setOnClickPendingIntent(R.id.widget_root,open(c,id*10,path));if(height<180){int pad=(int)((compact?8:12)*c.getResources().getDisplayMetrics().density);v.setViewPadding(R.id.widget_root,pad,pad,pad,pad);}manager.updateAppWidget(id,v);
 }
}
